--
-- Name: mv_airtemp; Type: MATERIALIZED VIEW; Schema: public; Owner: strax
--

CREATE MATERIALIZED VIEW public.mv_airtemp AS
 SELECT d.id,
    i.name,
    i.operator,
    i.stream,
    i.hzbnr,
    g.coord,
    public.st_x(g.coord) AS lon,
    public.st_y(g.coord) AS lat,
    g.x_offset,
    g.y_offset,
    c.name AS catchment_name,
    a1.val AS res_last_day_mean,
    a1.val_lt AS res_last_day_mean_lt,
    a1.valid_from AS res_last_day_mean_from,
    a1.valid_to AS res_last_day_mean_to,
    a2.val AS res_last_30days_mean,
    a2.val_lt AS res_last_30days_mean_lt,
    a2.valid_from AS res_last_30days_mean_from,
    a2.valid_to AS res_last_30days_mean_to,
    a3.val AS res_last_lastmonth_mean,
    a3.val_lt AS res_last_lastmonth_mean_lt,
    a3.valid_from AS res_last_lastmonth_mean_from,
    a3.valid_to AS res_last_lastmonth_mean_to,
    a4.val AS res_last_month_mean,
    a4.val_lt AS res_last_month_mean_lt,
    a4.valid_from AS res_last_month_mean_from,
    a4.valid_to AS res_last_month_mean_to,
    a5.val AS res_this_year_mean,
    a5.val_lt AS res_this_year_mean_lt,
    a5.valid_from AS res_this_year_mean_from,
    a5.valid_to AS res_this_year_mean_to,
    a6.val AS res_last_year_mean,
    a6.val_lt AS res_last_year_mean_lt,
    a6.valid_from AS res_last_year_mean_from,
    a6.valid_to AS res_last_year_mean_to,
    t.val AS last_val,
    t.dt AS last_dt,
    l.last_modified_at AS last_run
   FROM (((((((((((public.ds d
     JOIN public.ds_info i ON ((i.ds_id = d.id)))
     JOIN public.ds_geo g ON ((g.ds_id = d.id)))
     LEFT JOIN public.ds_catchments c ON ((c.id = d.catchment_id)))
     LEFT JOIN public.ds_tslog l ON ((l.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_day_mean'::text)) a1 ON ((a1.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_30days_mean'::text)) a2 ON ((a2.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_lastmonth_mean'::text)) a3 ON ((a3.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_month_mean'::text)) a4 ON ((a4.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'this_year_mean'::text)) a5 ON ((a5.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_year_mean'::text)) a6 ON ((a6.ds_id = d.id)))
     LEFT JOIN ( SELECT d_1.id,
            t_1.val,
            t_1.dt
           FROM (public.ds d_1
             LEFT JOIN ( SELECT max(t_2.val) AS val,
                    max(t_2.dt) AS dt,
                    t_2.ds_id
                   FROM (public.ts t_2
                     JOIN public.ts_categories c_1 ON (((c_1.id = t_2.cat_id) AND (c_1.name_short = 'live'::text) AND (t_2.dt <= (now())::date))))
                  GROUP BY t_2.ds_id) t_1 ON ((d_1.id = t_1.ds_id)))) t ON ((t.id = d.id)))
  WHERE ((i.parameter = 'Temperatur'::text) AND d.active AND (l.name = 'lt_webapp'::text))
  ORDER BY c.pos, d.pos, i.name
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_airtemp OWNER TO strax;

--
-- Name: mv_airtemp_basins; Type: MATERIALIZED VIEW; Schema: public; Owner: strax
--

CREATE MATERIALIZED VIEW public.mv_airtemp_basins AS
 SELECT gid,
    name,
    geom,
    (replace(replace(replace(replace(to_char(avg(res_last_day), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_day_string,
    COALESCE(avg(res_last_day), '-9999'::double precision) AS res_last_day,
    (replace(replace(replace(replace(to_char(avg(res_last_30days), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_30days_string,
    COALESCE(avg(res_last_30days), '-9999'::double precision) AS res_last_30days,
    (replace(replace(replace(replace(to_char(avg(res_last_lastmonth), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_lastmonth_string,
    COALESCE(avg(res_last_lastmonth), '-9999'::double precision) AS res_last_lastmonth,
    (replace(replace(replace(replace(to_char(avg(res_last_month), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_month_string,
    COALESCE(avg(res_last_month), '-9999'::double precision) AS res_last_month,
    (replace(replace(replace(replace(to_char(avg(res_this_year), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_this_year_string,
    COALESCE(avg(res_this_year), '-9999'::double precision) AS res_this_year,
    (replace(replace(replace(replace(to_char(avg(res_last_year), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_year_string,
    COALESCE(avg(res_last_year), '-9999'::double precision) AS res_last_year
   FROM ( SELECT b.gid,
            b.name,
            b.geom,
            (d.res_last_day_mean - (d.res_last_day_mean_lt)::double precision) AS res_last_day,
            (d.res_last_30days_mean - (d.res_last_30days_mean_lt)::double precision) AS res_last_30days,
            (d.res_last_lastmonth_mean - (d.res_last_lastmonth_mean_lt)::double precision) AS res_last_lastmonth,
            (d.res_last_month_mean - (d.res_last_month_mean_lt)::double precision) AS res_last_month,
            (d.res_this_year_mean - (d.res_this_year_mean_lt)::double precision) AS res_this_year,
            (d.res_last_year_mean - (d.res_last_year_mean_lt)::double precision) AS res_last_year
           FROM (public.mv_airtemp d
             JOIN public.geo_basins b ON (public.st_within(d.coord, b.geom)))
          ORDER BY b.gid) unnamed_subquery
  GROUP BY gid, name, geom
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_airtemp_basins OWNER TO strax;

--
-- Name: mv_discharge; Type: MATERIALIZED VIEW; Schema: public; Owner: strax
--

CREATE MATERIALIZED VIEW public.mv_discharge AS
 SELECT d.id,
    i.name,
    i.operator,
    i.stream,
    i.hzbnr,
    g.coord,
    public.st_x(g.coord) AS lon,
    public.st_y(g.coord) AS lat,
    g.x_offset,
    g.y_offset,
    c.name AS catchment_name,
    a1.val AS res_last_day_mean,
    a1.val_lt AS res_last_day_mean_lt,
    a1.valid_from AS res_last_day_mean_from,
    a1.valid_to AS res_last_day_mean_to,
    a2.val AS res_last_30days_mean,
    a2.val_lt AS res_last_30days_mean_lt,
    a2.valid_from AS res_last_30days_mean_from,
    a2.valid_to AS res_last_30days_mean_to,
    a3.val AS res_last_lastmonth_mean,
    a3.val_lt AS res_last_lastmonth_mean_lt,
    a3.valid_from AS res_last_lastmonth_mean_from,
    a3.valid_to AS res_last_lastmonth_mean_to,
    a4.val AS res_last_month_mean,
    a4.val_lt AS res_last_month_mean_lt,
    a4.valid_from AS res_last_month_mean_from,
    a4.valid_to AS res_last_month_mean_to,
    a5.val AS res_this_year_mean,
    a5.val_lt AS res_this_year_mean_lt,
    a5.valid_from AS res_this_year_mean_from,
    a5.valid_to AS res_this_year_mean_to,
    a6.val AS res_last_year_mean,
    a6.val_lt AS res_last_year_mean_lt,
    a6.valid_from AS res_last_year_mean_from,
    a6.valid_to AS res_last_year_mean_to,
    t.val AS last_val,
    t.dt AS last_dt,
    l.last_modified_at AS last_run
   FROM (((((((((((public.ds d
     JOIN public.ds_info i ON ((i.ds_id = d.id)))
     JOIN public.ds_geo g ON ((g.ds_id = d.id)))
     LEFT JOIN public.ds_catchments c ON ((c.id = d.catchment_id)))
     LEFT JOIN public.ds_tslog l ON ((l.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_day_mean'::text)) a1 ON ((a1.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_30days_mean'::text)) a2 ON ((a2.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_lastmonth_mean'::text)) a3 ON ((a3.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_month_mean'::text)) a4 ON ((a4.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'this_year_mean'::text)) a5 ON ((a5.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val,
            r.val_lt,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_year_mean'::text)) a6 ON ((a6.ds_id = d.id)))
     LEFT JOIN ( SELECT d_1.id,
            t_1.val,
            t_1.dt
           FROM (public.ds d_1
             LEFT JOIN ( SELECT max(t_2.val) AS val,
                    max(t_2.dt) AS dt,
                    t_2.ds_id
                   FROM (public.ts t_2
                     JOIN public.ts_categories c_1 ON (((c_1.id = t_2.cat_id) AND (c_1.name_short = 'live'::text) AND (t_2.dt <= (now())::date))))
                  GROUP BY t_2.ds_id) t_1 ON ((d_1.id = t_1.ds_id)))) t ON ((t.id = d.id)))
  WHERE ((i.parameter = 'Abfluss'::text) AND d.active AND (l.name = 'lt_webapp'::text))
  ORDER BY c.pos, d.pos, i.name
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_discharge OWNER TO strax;

--
-- Name: mv_discharge_basins; Type: MATERIALIZED VIEW; Schema: public; Owner: strax
--

CREATE MATERIALIZED VIEW public.mv_discharge_basins AS
 SELECT gid,
    name,
    geom,
    (replace(replace(replace(to_char(avg(res_last_day), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_day_string,
    COALESCE(avg(res_last_day), '-9999'::double precision) AS res_last_day,
    (replace(replace(replace(to_char(avg(res_last_30days), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_30days_string,
    COALESCE(avg(res_last_30days), '-9999'::double precision) AS res_last_30days,
    (replace(replace(replace(to_char(avg(res_last_lastmonth), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_lastmonth_string,
    COALESCE(avg(res_last_lastmonth), '-9999'::double precision) AS res_last_lastmonth,
    (replace(replace(replace(to_char(avg(res_last_month), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_month_string,
    COALESCE(avg(res_last_month), '-9999'::double precision) AS res_last_month,
    (replace(replace(replace(to_char(avg(res_this_year), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_this_year_string,
    COALESCE(avg(res_this_year), '-9999'::double precision) AS res_this_year,
    (replace(replace(replace(to_char(avg(res_last_year), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_year_string,
    COALESCE(avg(res_last_year), '-9999'::double precision) AS res_last_year
   FROM ( SELECT b.gid,
            b.name,
            b.geom,
            (((d.res_last_day_mean - (d.res_last_day_mean_lt)::double precision) / (d.res_last_day_mean_lt)::double precision) * (100)::double precision) AS res_last_day,
            (((d.res_last_30days_mean - (d.res_last_30days_mean_lt)::double precision) / (d.res_last_30days_mean_lt)::double precision) * (100)::double precision) AS res_last_30days,
            (((d.res_last_lastmonth_mean - (d.res_last_lastmonth_mean_lt)::double precision) / (d.res_last_lastmonth_mean_lt)::double precision) * (100)::double precision) AS res_last_lastmonth,
            (((d.res_last_month_mean - (d.res_last_month_mean_lt)::double precision) / (d.res_last_month_mean_lt)::double precision) * (100)::double precision) AS res_last_month,
            (((d.res_this_year_mean - (d.res_this_year_mean_lt)::double precision) / (d.res_this_year_mean_lt)::double precision) * (100)::double precision) AS res_this_year,
            (((d.res_last_year_mean - (d.res_last_year_mean_lt)::double precision) / (d.res_last_year_mean_lt)::double precision) * (100)::double precision) AS res_last_year
           FROM (public.mv_discharge d
             JOIN public.geo_basins b ON (public.st_within(d.coord, b.geom)))
          ORDER BY b.gid) unnamed_subquery
  GROUP BY gid, name, geom
  WITH NO DATA;


