CREATE MATERIALIZED VIEW public.mv_groundwater AS
 SELECT d.id,
    i.name,
    i.operator,
    i.stream,
    i.hzbnr,
    i.altitude,
    public.st_x(g.coord) AS lon,
    public.st_y(g.coord) AS lat,
    g.x_offset,
    g.y_offset,
    g.coord,
    c.name AS catchment_name,
    a1.val_min AS res_last_day_min,
    a1.val AS res_last_day_mean,
    a1.val_max AS res_last_day_max,
    a1.val_lt_min AS res_last_day_min_lt,
    a1.val_lt AS res_last_day_mean_lt,
    a1.val_lt_max AS res_last_day_max_lt,
    a1.valid_from AS res_last_day_from,
    a1.valid_to AS res_last_day_to,
    a2.val_min AS res_last_30days_min,
    a2.val AS res_last_30days_mean,
    a2.val_max AS res_last_30days_max,
    a2.val_lt_min AS res_last_30days_min_lt,
    a2.val_lt AS res_last_30days_mean_lt,
    a2.val_lt_max AS res_last_30days_max_lt,
    a2.valid_from AS res_last_30days_from,
    a2.valid_to AS res_last_30days_to,
    a3.val_min AS res_last_month_min,
    a3.val AS res_last_month_mean,
    a3.val_max AS res_last_month_max,
    a3.val_lt_min AS res_last_month_min_lt,
    a3.val_lt AS res_last_month_mean_lt,
    a3.val_lt_max AS res_last_month_max_lt,
    a3.valid_from AS res_last_month_from,
    a3.valid_to AS res_last_month_to,
    a4.val_min AS res_last_lastmonth_min,
    a4.val AS res_last_lastmonth_mean,
    a4.val_max AS res_last_lastmonth_max,
    a4.val_lt_min AS res_last_lastmonth_min_lt,
    a4.val_lt AS res_last_lastmonth_mean_lt,
    a4.val_lt_max AS res_last_lastmonth_max_lt,
    a4.valid_from AS res_last_lastmonth_from,
    a4.valid_to AS res_last_lastmonth_to,
    a5.val_min AS res_this_year_min,
    a5.val AS res_this_year_mean,
    a5.val_max AS res_this_year_max,
    a5.val_lt_min AS res_this_year_min_lt,
    a5.val_lt AS res_this_year_mean_lt,
    a5.val_lt_max AS res_this_year_max_lt,
    a5.valid_from AS res_this_year_from,
    a5.valid_to AS res_this_year_to,
    a6.val_min AS res_last_year_min,
    a6.val AS res_last_year_mean,
    a6.val_max AS res_last_year_max,
    a6.val_lt_min AS res_last_year_min_lt,
    a6.val_lt AS res_last_year_mean_lt,
    a6.val_lt_max AS res_last_year_max_lt,
    a6.valid_from AS res_last_year_from,
    a6.valid_to AS res_last_year_to,
    t.val AS last_val,
    t.dt AS last_dt,
    l.last_modified_at AS last_run
   FROM (((((((((((public.ds d
     JOIN public.ds_info i ON ((i.ds_id = d.id)))
     JOIN public.ds_geo g ON ((g.ds_id = d.id)))
     LEFT JOIN public.ds_catchments c ON ((c.id = d.catchment_id)))
     LEFT JOIN public.ds_tslog l ON ((l.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val_min,
            r.val_lt_min,
            r.val,
            r.val_lt,
            r.val_max,
            r.val_lt_max,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_day_mean'::text)) a1 ON ((a1.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val_min,
            r.val_lt_min,
            r.val,
            r.val_lt,
            r.val_max,
            r.val_lt_max,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_30days_mean'::text)) a2 ON ((a2.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val_min,
            r.val_lt_min,
            r.val,
            r.val_lt,
            r.val_max,
            r.val_lt_max,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_month_mean'::text)) a3 ON ((a3.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val_min,
            r.val_lt_min,
            r.val,
            r.val_lt,
            r.val_max,
            r.val_lt_max,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_lastmonth_mean'::text)) a4 ON ((a4.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val_min,
            r.val_lt_min,
            r.val,
            r.val_lt,
            r.val_max,
            r.val_lt_max,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'this_year_mean'::text)) a5 ON ((a5.ds_id = d.id)))
     LEFT JOIN ( SELECT a.ds_id,
            r.val_min,
            r.val_lt_min,
            r.val,
            r.val_lt,
            r.val_max,
            r.val_lt_max,
            r.valid_from,
            r.valid_to
           FROM (public.ds_results r
             JOIN public.ds_analysis a ON ((r.analysis_id = a.id)))
          WHERE (a.name = 'last_year_mean'::text)) a6 ON ((a6.ds_id = d.id)))
     LEFT JOIN ( SELECT d_1.id,
            t_1.val,
            t_1.dt
           FROM (public.ds d_1
             LEFT JOIN ( SELECT max(t_2.val) AS val,
                    max(t_2.dt) AS dt,
                    t_2.ds_id
                   FROM (public.ts t_2
                     JOIN public.ts_categories c_1 ON (((c_1.id = t_2.cat_id) AND (c_1.name_short = 'live'::text) AND (t_2.dt <= (now())::date))))
                  GROUP BY t_2.ds_id) t_1 ON ((d_1.id = t_1.ds_id)))) t ON ((t.id = d.id)))
  WHERE ((i.parameter = 'GWS'::text) AND d.active AND (l.name = 'lt_webapp'::text))
  ORDER BY c.pos, d.pos, i.name
  WITH NO DATA;


