--
-- Name: mv_groundwater_basins; Type: MATERIALIZED VIEW; Schema: public; Owner: strax
--

CREATE MATERIALIZED VIEW public.mv_groundwater_basins AS
 SELECT gid,
    name,
    geom,
    (replace(replace(replace(to_char(avg(res_last_day), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_day_string,
    COALESCE(avg(res_last_day), '-9999'::double precision) AS res_last_day,
    (replace(replace(replace(to_char(avg(res_last_30days), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_30days_string,
    COALESCE(avg(res_last_30days), '-9999'::double precision) AS res_last_30days,
    (replace(replace(replace(to_char(avg(res_last_lastmonth), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_lastmonth_string,
    COALESCE(avg(res_last_lastmonth), '-9999'::double precision) AS res_last_lastmonth,
    (replace(replace(replace(to_char(avg(res_last_month), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_month_string,
    COALESCE(avg(res_last_month), '-9999'::double precision) AS res_last_month,
    (replace(replace(replace(to_char(avg(res_this_year), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_this_year_string,
    COALESCE(avg(res_this_year), '-9999'::double precision) AS res_this_year,
    (replace(replace(replace(to_char(avg(res_last_year), 'PL999999999999999999'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text) || ' %'::text) AS res_last_year_string,
    COALESCE(avg(res_last_year), '-9999'::double precision) AS res_last_year
   FROM ( SELECT b.gid,
            b.name,
            b.geom,
                CASE
                    WHEN (d.res_last_day_mean < (d.res_last_day_mean_lt)::double precision) THEN (((d.res_last_day_mean_lt)::double precision - d.res_last_day_mean) / (((d.res_last_day_mean_lt - d.res_last_day_min_lt) / (100)::numeric))::double precision)
                    WHEN (d.res_last_day_mean > (d.res_last_day_mean_lt)::double precision) THEN (((d.res_last_day_mean_lt)::double precision - d.res_last_day_mean) / (((d.res_last_day_max_lt - d.res_last_day_mean_lt) / (100)::numeric))::double precision)
                    ELSE (0)::double precision
                END AS res_last_day,
                CASE
                    WHEN (d.res_last_30days_mean < (d.res_last_30days_mean_lt)::double precision) THEN (((d.res_last_30days_mean_lt)::double precision - d.res_last_30days_mean) / (((d.res_last_30days_mean_lt - d.res_last_30days_min_lt) / (100)::numeric))::double precision)
                    WHEN (d.res_last_30days_mean > (d.res_last_30days_mean_lt)::double precision) THEN (((d.res_last_30days_mean_lt)::double precision - d.res_last_30days_mean) / (((d.res_last_30days_max_lt - d.res_last_30days_mean_lt) / (100)::numeric))::double precision)
                    ELSE (0)::double precision
                END AS res_last_30days,
                CASE
                    WHEN (d.res_last_lastmonth_mean < (d.res_last_lastmonth_mean_lt)::double precision) THEN (((d.res_last_lastmonth_mean_lt)::double precision - d.res_last_lastmonth_mean) / (((d.res_last_lastmonth_mean_lt - d.res_last_lastmonth_min_lt) / (100)::numeric))::double precision)
                    WHEN (d.res_last_lastmonth_mean > (d.res_last_lastmonth_mean_lt)::double precision) THEN (((d.res_last_lastmonth_mean_lt)::double precision - d.res_last_lastmonth_mean) / (((d.res_last_lastmonth_max_lt - d.res_last_lastmonth_mean_lt) / (100)::numeric))::double precision)
                    ELSE (0)::double precision
                END AS res_last_lastmonth,
                CASE
                    WHEN (d.res_last_month_mean < (d.res_last_month_mean_lt)::double precision) THEN (((d.res_last_month_mean_lt)::double precision - d.res_last_month_mean) / (((d.res_last_month_mean_lt - d.res_last_month_min_lt) / (100)::numeric))::double precision)
                    WHEN (d.res_last_month_mean > (d.res_last_month_mean_lt)::double precision) THEN (((d.res_last_month_mean_lt)::double precision - d.res_last_month_mean) / (((d.res_last_month_max_lt - d.res_last_month_mean_lt) / (100)::numeric))::double precision)
                    ELSE (0)::double precision
                END AS res_last_month,
                CASE
                    WHEN (d.res_this_year_mean < (d.res_this_year_mean_lt)::double precision) THEN (((d.res_this_year_mean_lt)::double precision - d.res_this_year_mean) / (((d.res_this_year_mean_lt - d.res_this_year_min_lt) / (100)::numeric))::double precision)
                    WHEN (d.res_this_year_mean > (d.res_this_year_mean_lt)::double precision) THEN (((d.res_this_year_mean_lt)::double precision - d.res_this_year_mean) / (((d.res_this_year_max_lt - d.res_this_year_mean_lt) / (100)::numeric))::double precision)
                    ELSE (0)::double precision
                END AS res_this_year,
                CASE
                    WHEN (d.res_last_year_mean < (d.res_last_year_mean_lt)::double precision) THEN (((d.res_last_year_mean_lt)::double precision - d.res_last_year_mean) / (((d.res_last_year_mean_lt - d.res_last_year_min_lt) / (100)::numeric))::double precision)
                    WHEN (d.res_last_year_mean > (d.res_last_year_mean_lt)::double precision) THEN (((d.res_last_year_mean_lt)::double precision - d.res_last_year_mean) / (((d.res_last_year_max_lt - d.res_last_year_mean_lt) / (100)::numeric))::double precision)
                    ELSE (0)::double precision
                END AS res_last_year
           FROM (public.mv_groundwater d
             JOIN public.geo_basins b ON (public.st_within(d.coord, b.geom)))
          ORDER BY b.gid) unnamed_subquery
  GROUP BY gid, name, geom
  WITH NO DATA;


