    i.hzbnr,
    g.coord,
    public.st_x(g.coord) AS lon,
    public.st_y(g.coord) AS lat,
    g.x_offset,
    g.y_offset,
    c.name AS catchment_name,
    a1.val AS res_last_30days,
    a1.val_lt AS res_last_30days_lt,
