    a2.val_lt AS res_last_lastmonth_lt,
    a2.valid_from AS res_last_lastmonth_from,
    a2.valid_to AS res_last_lastmonth_to,
    a3.val AS res_last_month,
    a3.val_lt AS res_last_month_lt,
    a3.valid_from AS res_last_month_from,
    a3.valid_to AS res_last_month_to,
    a4.val AS res_this_year,
    a4.val_lt AS res_this_year_lt,
    a4.valid_from AS res_this_year_from,
    a4.valid_to AS res_this_year_to,
    a5.val AS res_last_year,
    a5.val_lt AS res_last_year_lt,
    a5.valid_from AS res_last_year_from,
    a5.valid_to AS res_last_year_to,
    a4.val AS last_val,
    a4.valid_to AS last_dt,
    l.last_modified_at AS last_run
   FROM (((((((((public.ds d
     JOIN public.ds_info i ON ((i.ds_id = d.id)))
