--

CREATE MATERIALIZED VIEW public.mv_watertemp_basins AS
 SELECT gid,
    name,
    geom,
    (replace(replace(replace(replace(to_char(avg(res_last_day), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_day_string,
    COALESCE(avg(res_last_day), '-9999'::double precision) AS res_last_day,
    (replace(replace(replace(replace(to_char(avg(res_last_30days), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_30days_string,
    COALESCE(avg(res_last_30days), '-9999'::double precision) AS res_last_30days,
    (replace(replace(replace(replace(to_char(avg(res_last_lastmonth), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_lastmonth_string,
    COALESCE(avg(res_last_lastmonth), '-9999'::double precision) AS res_last_lastmonth,
    (replace(replace(replace(replace(to_char(avg(res_last_month), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_month_string,
    COALESCE(avg(res_last_month), '-9999'::double precision) AS res_last_month,
    (replace(replace(replace(replace(to_char(avg(res_this_year), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_this_year_string,
    COALESCE(avg(res_this_year), '-9999'::double precision) AS res_this_year,
    (replace(replace(replace(replace(to_char(avg(res_last_year), 'PL99999999999999999.9'::text), ' '::text, ''::text), '+'::text, '+ '::text), '-'::text, '- '::text), ' .'::text, ' 0.'::text) || ' °C'::text) AS res_last_year_string,
    COALESCE(avg(res_last_year), '-9999'::double precision) AS res_last_year
   FROM ( SELECT b.gid,
            b.name,
            b.geom,
            (d.res_last_day_mean - (d.res_last_day_mean_lt)::double precision) AS res_last_day,
            (d.res_last_30days_mean - (d.res_last_30days_mean_lt)::double precision) AS res_last_30days,
